export const engineFiles = {
  "engine/index.js": "// LoreMail GM Engine — public API\r\n// Only GMEngine is exported. All other modules are internal.\r\nexport { GMEngine } from './src/engine.js';\r\n",
  "engine/src/canon-manager.js": "import { CompressionPromptBuilder } from './compression-prompt.js';\n/**\n * CanonManager — two-layer canon structure (DEEP HISTORY / RECENT HISTORY).\n * Tracks word count, triggers compression. Append-only — no tags.\n */\nexport class CanonManager {\n  constructor(worldState, engineConfig) {\n    this.ws = worldState;\n    this.config = engineConfig;\n    this.recentWordLimit = engineConfig.canon_recent_word_limit ?? 4000;\n    this.deepSummaryTarget = engineConfig.canon_deep_summary_target ?? 800;\n    this.compressionPromptBuilder = new CompressionPromptBuilder();\n  }\n  _wordCount(text) {\n    return text.trim().split(/\\s+/).filter(Boolean).length;\n  }\n  async isCompressionNeeded() {\n    const canon = await this.ws.readCanon();\n    const { recent } = this.ws.parseSections(canon);\n    return this._wordCount(recent) >= this.recentWordLimit;\n  }\n  async recentWordCount() {\n    const canon = await this.ws.readCanon();\n    const { recent } = this.ws.parseSections(canon);\n    return this._wordCount(recent);\n  }\n  /**\n   * Append a new entry to RECENT HISTORY.\n   * The entry text should already include the ### heading.\n   */\n  async appendEntry(entryText) {\n    await this.ws.appendToCanon('\\n' + entryText.trim());\n  }\n  /**\n   * Run compression: oldest 50% of RECENT HISTORY entries → DEEP HISTORY.\n   */\n  async runCompression(modelClient) {\n    const canon = await this.ws.readCanon();\n    const { recent } = this.ws.parseSections(canon);\n    const entries = recent.split(/(?=### )/).filter(s => s.trim());\n    if (entries.length < 2) return;\n    const splitIdx = Math.ceil(entries.length / 2);\n    const toCompress = entries.slice(0, splitIdx);\n    const toKeep = entries.slice(splitIdx);\n    const facts = await this.ws.readFacts();\n    const anchorList = this._buildAnchorList(toCompress.join('\\n'), facts);\n    const CHUNK_SIZE = 5;\n    const compressedBlocks = [];\n    for (let i = 0; i < toCompress.length; i += CHUNK_SIZE) {\n      const chunk = toCompress.slice(i, i + CHUNK_SIZE);\n      const messages = this.compressionPromptBuilder.buildCompressionChunkPrompt(chunk, anchorList);\n      try {\n        const compressed = await modelClient.chat(messages, { temperature: 0.2, maxTokens: 600 });\n        compressedBlocks.push(compressed.trim());\n      } catch (err) {\n        console.error('Compression chunk failed, skipping:', err.message);\n      }\n    }\n    if (compressedBlocks.length === 0) return;\n    await this.ws.appendToDeepHistory(compressedBlocks.join('\\n\\n'));\n    await this.ws.replaceRecentHistory(toKeep.join('\\n\\n'));\n  }\n  /** Initialize blank canon structure for a new game */\n  async initBlank() {\n    await this.ws.writeFile('world/canon.md', this.ws.rebuildCanon('', ''));\n  }\n  _buildAnchorList(text, facts) {\n    const anchors = new Set();\n    const capPhrases = text.match(/[A-Z][a-z]+(?:\\s+[A-Z][a-z]+)+/g) ?? [];\n    capPhrases.forEach(p => anchors.add(p));\n    const capWords = text.match(/(?<=[.!?]\\s+|^)(?![A-Z][a-z]+[.,])([A-Z][a-z]{3,})/gm) ?? [];\n    capWords.forEach(w => anchors.add(w));\n    if (facts) {\n      const factProper = facts.match(/[A-Z][a-z]+(?:\\s+[A-Z][a-z]+)*/g) ?? [];\n      factProper.forEach(p => anchors.add(p));\n    }\n    return [...anchors].slice(0, 30);\n  }\n}\n",
  "engine/src/compression-prompt.js": "/**\r\n * CompressionPromptBuilder — builds prompts for the canon compression step.\r\n * Separate from prompt-builder.js because compression is a fundamentally different\r\n * task with different instructions, lower temperature, and different output format.\r\n */\r\nexport class CompressionPromptBuilder {\r\n  /**\r\n   * Build a compression prompt for a chunk of canon entries.\r\n   * @param {string[]} chunk - Array of raw canon entry strings (≤5 entries)\r\n   * @param {string[]} anchorList - Proper nouns and known facts that must survive compression\r\n   */\r\n  buildCompressionChunkPrompt(chunk, anchorList = []) {\r\n    const system = `You are compressing historical records into a permanent archive.\r\nYour output will never be revised. Write with the precision of a historian\r\nwho knows these words will outlast their author.\r\n\r\nRules:\r\n- Third person, past tense, chronicle voice\r\n- Every proper noun in the anchor list must appear in your output by name\r\n- Do not invent anything not present in the source entries\r\n- Do not resolve ambiguities the source entries left open\r\n- Retain the earliest and latest established dates from the entries\r\n- Output only the compressed block. No preamble.`;\r\n\r\n    // Extract titles and dates from entries for the output skeleton\r\n    const titles = chunk.map(e => {\r\n      const titleMatch = e.match(/### (.+)/);\r\n      return titleMatch ? titleMatch[1].trim() : 'Untitled';\r\n    });\r\n\r\n    const dates = chunk.map(e => {\r\n      const dateMatch = e.match(/established: (\\d{4}-\\d{2}-\\d{2})/);\r\n      return dateMatch ? dateMatch[1] : null;\r\n    }).filter(Boolean);\r\n\r\n    const earliestDate = dates.sort()[0] ?? '';\r\n    const latestDate = dates.sort().at(-1) ?? '';\r\n\r\n    const anchorBlock = anchorList.length > 0\r\n      ? `ANCHOR LIST — every item here must appear in your output:\\n${anchorList.map(a => `- ${a}`).join('\\n')}\\n\\n`\r\n      : '';\r\n\r\n    const user = `Compress the following ${chunk.length} history ${chunk.length === 1 ? 'entry' : 'entries'} into a single archived block.\r\n\r\n${anchorBlock}OUTPUT FORMAT:\r\n**${titles.join(' / ')}**\r\n*${earliestDate}${latestDate && latestDate !== earliestDate ? ` – ${latestDate}` : ''}*\r\n\r\n{compressed prose, 2–4 sentences per original entry, combined}\r\n\r\nSOURCE ENTRIES:\r\n${chunk.join('\\n\\n---\\n\\n')}`;\r\n\r\n    return [\r\n      { role: 'system', content: system },\r\n      { role: 'user', content: user },\r\n    ];\r\n  }\r\n}\r\n",
  "engine/src/consistency.js": "/**\r\n * ConsistencyChecker — pre-commit check of proposed canon additions.\r\n * If conflicts are found, resolves them via a second model call rather than blocking.\r\n */\r\nexport class ConsistencyChecker {\r\n  constructor(worldState, modelClient) {\r\n    this.ws = worldState;\r\n    this.modelClient = modelClient;\r\n  }\r\n\r\n  /**\r\n   * Check proposed addition and return a (possibly rewritten) resolved addition.\r\n   * Returns { consistent, conflicts, resolvedAddition }\r\n   */\r\n  async check(proposedAddition) {\r\n    const facts = await this.ws.readFacts();\r\n    if (!facts?.trim()) {\r\n      return { consistent: true, conflicts: [], resolvedAddition: proposedAddition };\r\n    }\r\n\r\n    // Step 1 — identify conflicts\r\n    const checkMessages = [\r\n      {\r\n        role: 'system',\r\n        content: `You are a continuity editor for a world history record.\r\n\r\nYou will be given:\r\n1. A list of established facts (immutable)\r\n2. A proposed new history entry\r\n\r\nYour job: identify any direct contradictions between the proposed entry and the established facts.\r\n\r\nA contradiction is when the proposed entry states or implies something that cannot be\r\nsimultaneously true with an established fact.\r\n\r\nRespond with JSON only:\r\n{ \"consistent\": boolean, \"conflicts\": string[] }`,\r\n      },\r\n      {\r\n        role: 'user',\r\n        content: `ESTABLISHED FACTS:\\n${facts}\\n\\nPROPOSED ENTRY:\\n${proposedAddition}`,\r\n      },\r\n    ];\r\n\r\n    let result;\r\n    try {\r\n      result = await this.modelClient.chatJson(checkMessages, { temperature: 0.1, maxTokens: 400 });\r\n    } catch {\r\n      return { consistent: true, conflicts: [], resolvedAddition: proposedAddition };\r\n    }\r\n\r\n    const { consistent, conflicts = [] } = result;\r\n\r\n    if (consistent || conflicts.length === 0) {\r\n      return { consistent: true, conflicts: [], resolvedAddition: proposedAddition };\r\n    }\r\n\r\n    // Step 2 — resolve the conflict via a rewrite\r\n    const resolveMessages = [\r\n      {\r\n        role: 'system',\r\n        content: `A proposed history entry conflicts with established facts.\r\nRewrite the entry so that both the existing facts and the new information are simultaneously true.\r\nFind the most dramatically interesting reconciliation.\r\nDo not reject or omit the new information — recontextualise it.\r\nOutput only the rewritten entry. Same format as the original (### heading etc).\r\nNo preamble.`,\r\n      },\r\n      {\r\n        role: 'user',\r\n        content: `ESTABLISHED FACTS:\\n${facts}\\n\\nCONFLICTS IDENTIFIED:\\n${conflicts.map(c => `- ${c}`).join('\\n')}\\n\\nORIGINAL PROPOSED ENTRY:\\n${proposedAddition}`,\r\n      },\r\n    ];\r\n\r\n    try {\r\n      const resolved = await this.modelClient.chat(resolveMessages, { temperature: 0.3, maxTokens: 400 });\r\n      return { consistent: false, conflicts, resolvedAddition: resolved.trim() || proposedAddition };\r\n    } catch {\r\n      return { consistent: false, conflicts, resolvedAddition: proposedAddition };\r\n    }\r\n  }\r\n}",
  "engine/src/engine.js": "import { WorldState } from './world-state.js';\nimport { CanonManager } from './canon-manager.js';\nimport { FactExtractor } from './fact-extractor.js';\nimport { ConsistencyChecker } from './consistency.js';\nimport { PromptBuilder } from './prompt-builder.js';\nimport { ModelClient } from './model-client.js';\nimport { StatusWriter } from './status-writer.js';\n\n/**\n * GMEngine — public API for the LoreMail GM engine.\n */\nexport class GMEngine {\n  constructor({ repoPath, model, apiToken, engineConfig = {}, baseUrl }) {\n    this.repoPath = repoPath;\n    this.engineConfig = engineConfig;\n\n    this.ws = new WorldState(repoPath);\n    this.modelClient = new ModelClient({\n      model,\n      apiToken,\n      baseUrl,\n      defaultTemperature: engineConfig.temperature ?? 0.4,\n      defaultMaxTokens: 1500,\n    });\n    this.canonManager = new CanonManager(this.ws, engineConfig);\n    this.factExtractor = new FactExtractor(this.ws, this.modelClient);\n    this.consistencyChecker = new ConsistencyChecker(this.ws, this.modelClient);\n    this.promptBuilder = new PromptBuilder();\n    this._statusWriter = new StatusWriter(this.ws);\n  }\n\n  /**\n   * Generate the world seed on first game creation.\n   * Writes seed.md and the first canon entry.\n   */\n  async generateWorldSeed({ flavour, era, tone, gmStyle, game, founderCharacter }) {\n    const messages = this.promptBuilder.buildSeedPrompt({\n      worldName: game?.name,\n      flavour,\n      era,\n      tone,\n      gmStyle,\n      founderCharacter,\n    });\n\n    const result = await this.modelClient.chatJson(messages, { temperature: 0.6, maxTokens: 800 });\n\n    const seed = result.seed ?? result;\n    const firstCanonEntry = result.first_canon_entry;\n\n    await this.ws.writeSeed(typeof seed === 'string' ? seed : JSON.stringify(seed));\n    await this.canonManager.initBlank();\n\n    if (firstCanonEntry) {\n      await this.canonManager.appendEntry(firstCanonEntry);\n    }\n\n    // Seed the founder's starting location as the first map node\n    if (result.map_updates) {\n      const now = Math.floor(Date.now() / 1000);\n      await this.ws.updateMapJson(result.map_updates, now);\n    }\n\n    return { seed, firstCanonEntry };\n  }\n\n  /**\n   * Process a single delivered letter.\n   * Returns a GMDeliveryResult object.\n   */\n  async processDelivery({ letter, from, to, game, sentAt }) {\n    const eventsWindow = this.engineConfig.events_window ?? 20;\n\n    const [\n      seed, facts, canonRaw, events, gmNotes,\n      senderCharacter, senderLocation, recipientCharacter, recipientLocation,\n    ] = await Promise.all([\n      this.ws.readSeed(),\n      this.ws.readFacts(),\n      this.ws.readCanon(),\n      this.ws.readEvents(eventsWindow),\n      this.ws.readGmNotes(),\n      this.ws.readCharacter(from),\n      this.ws.readLocation(from),\n      this.ws.readCharacter(to),\n      this.ws.readLocation(to),\n    ]);\n\n    const { deep: deepHistory, recent: recentHistory } = this.ws.parseSections(canonRaw);\n\n    const senderPlayer = game.players?.find(p => p.id === from);\n    const recipientPlayer = game.players?.find(p => p.id === to);\n    const senderName = senderPlayer?.character ?? from;\n    const recipientName = recipientPlayer?.character ?? to;\n\n    const messages = this.promptBuilder.buildDeliveryPrompt({\n      seed, facts, deepHistory, recentHistory, events, gmNotes,\n      senderCharacter, senderLocation, recipientCharacter, recipientLocation,\n      letterBody: letter, senderName, recipientName, sentAt, game,\n    });\n\n    let gmResponse;\n    try {\n      gmResponse = await this.modelClient.chatJson(messages);\n    } catch (err) {\n      throw new Error(`GM model call failed: ${err.message}`);\n    }\n\n    // Fill defaults for missing fields\n    gmResponse.next_letter_travel_hours = Math.max(1, parseInt(gmResponse.next_letter_travel_hours) || (game.default_travel_hours ?? 24));\n\n    let canonAdditionToWrite = gmResponse.canon_addition ?? null;\n    let consistencyConflict = false;\n\n    // Consistency check before writing\n    if (this.engineConfig.consistency_check !== false && canonAdditionToWrite) {\n      const check = await this.consistencyChecker.check(canonAdditionToWrite);\n      consistencyConflict = !check.consistent;\n      canonAdditionToWrite = check.resolvedAddition;\n    }\n\n    // Append canon entry (model produces full ### {Title} formatted entry)\n    if (canonAdditionToWrite) {\n      await this.canonManager.appendEntry(canonAdditionToWrite);\n    }\n\n    // Fact extraction\n    if (this.engineConfig.fact_extraction !== false && canonAdditionToWrite) {\n      await this.factExtractor.extractFacts(canonAdditionToWrite);\n    }\n\n    // Append world event\n    if (gmResponse.world_event) {\n      const timestamp = new Date().toISOString().split('T')[0];\n      await this.ws.appendToFile('world/events.md', `\\n### ${timestamp}\\n${gmResponse.world_event}`);\n    }\n\n    // Append GM notes\n    if (gmResponse.gm_notes_addition) {\n      const timestamp = new Date().toISOString();\n      await this.ws.appendToFile('world/gm-notes.md', `\\n<!-- ${timestamp} -->\\n${gmResponse.gm_notes_addition}`);\n    }\n\n    // Update character files if model provided updates\n    if (gmResponse.sender_character_update) {\n      await this.ws.updateCharacter(from, gmResponse.sender_character_update);\n    }\n    if (gmResponse.recipient_character_update) {\n      await this.ws.updateCharacter(to, gmResponse.recipient_character_update);\n    }\n\n    // Write world lore JSON files\n    const loreNow = Math.floor(Date.now() / 1000);\n    if (gmResponse.map_updates?.new_nodes?.length || gmResponse.map_updates?.new_edges?.length) {\n      await this.ws.updateMapJson(gmResponse.map_updates, loreNow);\n    }\n    if (gmResponse.new_people?.length || gmResponse.updated_people?.length) {\n      await this.ws.updatePeopleJson({\n        new_people: gmResponse.new_people,\n        updated_people: gmResponse.updated_people,\n      }, loreNow);\n    }\n    if (gmResponse.new_factions?.length || gmResponse.updated_factions?.length) {\n      await this.ws.updateFactionsJson({\n        new_factions: gmResponse.new_factions,\n        updated_factions: gmResponse.updated_factions,\n      }, loreNow);\n    }\n    if (gmResponse.timeline_entry?.id) {\n      await this.ws.appendTimelineEntry(gmResponse.timeline_entry, loreNow);\n    }\n\n    // Update player character locations on the map\n    if (gmResponse.sender_location_node_id) {\n      await this.ws.updatePlayerLocationOnMap(from, gmResponse.sender_location_node_id);\n    }\n    if (gmResponse.recipient_location_node_id) {\n      await this.ws.updatePlayerLocationOnMap(to, gmResponse.recipient_location_node_id);\n    }\n\n    return {\n      success: true,\n      canonAddition: canonAdditionToWrite,\n      worldEvent: gmResponse.world_event ?? null,\n      gmNotesAddition: gmResponse.gm_notes_addition ?? null,\n      senderCharacterUpdate: gmResponse.sender_character_update ?? null,\n      recipientCharacterUpdate: gmResponse.recipient_character_update ?? null,\n      senderLocationUpdate: gmResponse.sender_location_update ?? null,\n      recipientLocationUpdate: gmResponse.recipient_location_update ?? null,\n      nextLetterTravelHours: gmResponse.next_letter_travel_hours,\n      consistencyConflict,\n      error: null,\n    };\n  }\n\n  /**\n   * Canonize a newly-joined player's starting location into the world map.\n   * Called via the `player_joined` trigger — runs even when there are no pending letters.\n   */\n  async processPlayerJoin({ playerId, game }) {\n    const [seed, facts, playerCharacter, playerLocation] = await Promise.all([\n      this.ws.readSeed(),\n      this.ws.readFacts(),\n      this.ws.readCharacter(playerId),\n      this.ws.readLocation(playerId),\n    ]);\n\n    const location = playerLocation?.trim();\n    if (!location || location === 'Unknown') {\n      return { success: true, skipped: true, reason: 'no location set' };\n    }\n\n    const map = await this.ws.readWorldJson('world/map.json');\n\n    // Normalize helper: lowercase, collapse non-alphanumeric to spaces\n    const norm = s => s.toLowerCase().replace(/[^a-z0-9]/g, ' ').replace(/\\s+/g, ' ').trim();\n    const locNorm  = norm(location);\n    const locWords = locNorm.split(' ').filter(w => w.length > 3);\n\n    // Check if a node for this location already exists (exact label, id, or\n    // fuzzy word-overlap match so we don't duplicate near-identical place names)\n    const matchingNode = map.nodes.find(n => {\n      const nl = norm(n.label ?? '');\n      if (!nl) return false;\n      if (nl === locNorm) return true;\n      if (n.id === locNorm.replace(/\\s+/g, '-')) return true;\n      // All significant words of the shorter label appear in the longer string\n      const nlWords   = nl.split(' ').filter(w => w.length > 3);\n      const shorter   = nlWords.length <= locWords.length ? nlWords : locWords;\n      const longerStr = nlWords.length <= locWords.length ? locNorm : nl;\n      return shorter.length >= 2 && shorter.every(w => longerStr.includes(w));\n    });\n\n    if (matchingNode) {\n      // Location is already represented on the map — link the player to that node\n      // instead of creating a duplicate, then exit early.\n      if (!map.player_locations?.[playerId]) {\n        await this.ws.updatePlayerLocationOnMap(playerId, matchingNode.id);\n      }\n      return { success: true, skipped: true, reason: 'location already on map', nodeId: matchingNode.id };\n    }\n\n    const playerEntry = game.players?.find(p => p.id === playerId);\n    const characterName = playerEntry?.character ?? playerId;\n\n    const messages = this.promptBuilder.buildPlayerJoinPrompt({\n      seed, facts, playerCharacter, playerLocation: location, characterName, game,\n      existingNodes: map.nodes,   // give the GM the current node list to avoid duplication\n    });\n\n    let gmResponse;\n    try {\n      gmResponse = await this.modelClient.chatJson(messages, { temperature: 0.5, maxTokens: 900 });\n    } catch (err) {\n      throw new Error(`GM model call failed (player_joined): ${err.message}`);\n    }\n\n    const now = Math.floor(Date.now() / 1000);\n\n    if (gmResponse.map_updates?.new_nodes?.length) {\n      await this.ws.updateMapJson(gmResponse.map_updates, now);\n    }\n    if (gmResponse.canon_addition) {\n      await this.canonManager.appendEntry(gmResponse.canon_addition);\n    }\n    if (gmResponse.world_event) {\n      const timestamp = new Date().toISOString().split('T')[0];\n      await this.ws.appendToFile('world/events.md', `\\n### ${timestamp}\\n${gmResponse.world_event}`);\n    }\n    if (gmResponse.gm_notes_addition) {\n      const timestamp = new Date().toISOString();\n      await this.ws.appendToFile('world/gm-notes.md', `\\n<!-- ${timestamp} -->\\n${gmResponse.gm_notes_addition}`);\n    }\n    if (gmResponse.player_location_node_id) {\n      await this.ws.updatePlayerLocationOnMap(playerId, gmResponse.player_location_node_id);\n    }\n\n    return { success: true, skipped: false };\n  }\n\n  /** Generate the closing chronicle */\n  async generateChronicle({ game }) {\n    const [seed, facts, canon, events] = await Promise.all([\n      this.ws.readSeed(),\n      this.ws.readFacts(),\n      this.ws.readCanon(),\n      this.ws.readEvents(100),\n    ]);\n\n    const characterParts = await Promise.all(\n      (game.players ?? [])\n        .filter(p => p.joined && !p.removed && p.character)\n        .map(async p => {\n          const [char, loc] = await Promise.all([\n            this.ws.readCharacter(p.id),\n            this.ws.readLocation(p.id),\n          ]);\n          return `### ${p.character}\\n${char}\\nLast known location: ${loc}`;\n        }),\n    );\n\n    const messages = this.promptBuilder.buildChroniclePrompt({\n      seed, facts, canon, events,\n      characters: characterParts.join('\\n\\n'),\n      game,\n    });\n\n    const chronicle = await this.modelClient.chat(messages, { temperature: 0.5, maxTokens: 2000 });\n    await this.ws.writeChronicle(chronicle);\n    return chronicle;\n  }\n\n\n  /**\n   * Chapterize: summarize the current RECENT HISTORY into a numbered chapter,\n   * save it to world/chapters.json, then move the entries to DEEP HISTORY.\n   */\n  async processChapterize({ game }) {\n    const [canon, facts, seed] = await Promise.all([\n      this.ws.readCanon(),\n      this.ws.readFacts(),\n      this.ws.readSeed(),\n    ]);\n\n    // Read recent content before modifying the file\n    const { recent } = this.ws.parseSections(canon);\n    const entries = recent.split(/(?=### )/).filter(s => s.trim());\n    if (!entries.length) {\n      return { success: false, reason: 'No canon entries to chapterize' };\n    }\n\n    const chaptersData = await this.ws.readChaptersJson();\n    const nextNumber = (chaptersData.chapters?.length ?? 0) + 1;\n\n    const messages = this.promptBuilder.buildChapterizePrompt({\n      seed, facts,\n      canonEntries: entries.join('\\n\\n'),\n      chapterNumber: nextNumber,\n      game,\n    });\n\n    let gmResponse;\n    try {\n      gmResponse = await this.modelClient.chatJson(messages, { temperature: 0.4, maxTokens: 600 });\n    } catch (err) {\n      throw new Error(`GM chapterize call failed: ${err.message}`);\n    }\n\n    const chapter = {\n      number: nextNumber,\n      title: gmResponse.chapter_title ?? `Chapter ${nextNumber}`,\n      summary: gmResponse.chapter_summary ?? '',\n      created_at: Math.floor(Date.now() / 1000),\n    };\n\n    await this.ws.appendChapterJson(chapter);\n\n    // Single atomic operation — one read, one write\n    await this.ws.chapterizeCanon();\n\n    return { success: true, chapter };\n  }\n  /** Write run status — always called by gm.js at the end of a run */\n  async writeStatus(payload) {\n    return await this._statusWriter.write(payload);\n  }\n\n  async summarizeIfNeeded() {\n    if (await this.canonManager.isCompressionNeeded()) {\n      await this.canonManager.runCompression(this.modelClient);\n      return true;\n    }\n    return false;\n  }\n\n  /** Expose statusWriter for gm.js compatibility */\n  get statusWriter() { return this._statusWriter; }\n\n  get worldState() { return this.ws; }\n}",
  "engine/src/fact-extractor.js": "/**\r\n * FactExtractor — after each canon addition, extracts concrete facts\r\n * as a flat bullet list into canon-facts.md. Runs at temperature 0.3.\r\n */\r\nexport class FactExtractor {\r\n  constructor(worldState, modelClient) {\r\n    this.ws = worldState;\r\n    this.modelClient = modelClient;\r\n  }\r\n\r\n  async extractFacts(newCanonText) {\r\n    if (!newCanonText?.trim()) return;\r\n\r\n    const existingFacts = await this.ws.readFacts();\r\n\r\n    const messages = [\r\n      {\r\n        role: 'system',\r\n        content: `You are extracting hard facts from a world history entry.\r\n\r\nYour output is a bullet list only. No preamble. No commentary.\r\n\r\nRules:\r\n- One fact per bullet\r\n- Each fact is a single declarative sentence\r\n- Concrete and specific — names, places, relationships, states of affairs\r\n- No inference, no interpretation — only what is explicitly stated\r\n- No duplicates with existing facts (existing facts provided below)`,\r\n      },\r\n      {\r\n        role: 'user',\r\n        content: `EXISTING FACTS:\\n${existingFacts || '(none yet)'}\\n\\nNEW ENTRY TO EXTRACT FROM:\\n${newCanonText}\\n\\nOutput only the new bullet points. If there are no new facts not already captured, output nothing.`,\r\n      },\r\n    ];\r\n\r\n    const facts = await this.modelClient.chat(messages, { temperature: 0.3, maxTokens: 800 });\r\n    if (!facts?.trim()) return;\r\n\r\n    // Append as flat bullets with no heading or date wrapper\r\n    await this.ws.appendToFile('world/canon-facts.md', facts.trim());\r\n  }\r\n}",
  "engine/src/model-client.js": "/**\r\n * ModelClient — wrapper around the GitHub Models inference API (OpenAI-compatible endpoint).\r\n * Base URL: https://models.github.ai/inference\r\n *\r\n * Authentication: GitHub PAT with models:read permission, used as a Bearer token.\r\n * No Copilot subscription required — available to all GitHub users (free-tier rate limits apply).\r\n *\r\n * Model IDs use provider/model-name format, e.g. \"openai/gpt-4.1\", \"meta/llama-3.3-70b-instruct\".\r\n *\r\n * Handles retries on transient errors and JSON parse failures.\r\n */\r\nexport class ModelClient {\r\n  constructor({ model, apiToken, baseUrl, defaultTemperature = 0.4, defaultMaxTokens = 1500 }) {\r\n    this.model = model ?? 'openai/gpt-4.1';\r\n    this.apiToken = apiToken;\r\n    this.baseUrl = baseUrl ?? 'https://models.github.ai/inference';\r\n    this.defaultTemperature = defaultTemperature;\r\n    this.defaultMaxTokens = defaultMaxTokens;\r\n  }\r\n\r\n  /** Send chat request, returns raw string */\r\n  async chat(messages, opts = {}) {\r\n    const temperature = opts.temperature ?? this.defaultTemperature;\r\n    const maxTokens = opts.maxTokens ?? this.defaultMaxTokens;\r\n    return await this._requestWithRetry({ model: this.model, messages, temperature, max_tokens: maxTokens }, 3);\r\n  }\r\n\r\n  /**\r\n   * Send chat request, parse and return JSON.\r\n   * Retries once with a correction message if JSON parse fails.\r\n   */\r\n  async chatJson(messages, opts = {}) {\r\n    const raw = await this.chat(messages, opts);\r\n    try {\r\n      const jsonMatch = raw.match(/\\{[\\s\\S]*\\}/);\r\n      return JSON.parse(jsonMatch?.[0] ?? raw);\r\n    } catch {\r\n      // Retry with format correction appended\r\n      const correctionMessages = [\r\n        ...messages,\r\n        { role: 'assistant', content: raw },\r\n        {\r\n          role: 'user',\r\n          content: 'Your previous response could not be parsed as JSON.\\nRespond with raw JSON only. No markdown fences. No preamble.',\r\n        },\r\n      ];\r\n      const retry = await this.chat(correctionMessages, opts);\r\n      const retryMatch = retry.match(/\\{[\\s\\S]*\\}/);\r\n      return JSON.parse(retryMatch?.[0] ?? retry);\r\n    }\r\n  }\r\n\r\n  async _requestWithRetry(body, maxRetries) {\r\n    let lastError;\r\n    const delays = [2000, 4000, 8000];\r\n    for (let attempt = 0; attempt < maxRetries; attempt++) {\r\n      try {\r\n        const response = await fetch(`${this.baseUrl}/chat/completions`, {\r\n          method: 'POST',\r\n          headers: {\r\n            'Content-Type': 'application/json',\r\n            Authorization: `Bearer ${this.apiToken}`,\r\n            'X-GitHub-Api-Version': '2022-11-28',\r\n          },\r\n          body: JSON.stringify(body),\r\n        });\r\n\r\n        if (!response.ok) {\r\n          const errorText = await response.text();\r\n          // Never retry on auth errors\r\n          if (response.status === 401 || response.status === 403) {\r\n            throw new Error(`Auth error ${response.status}: ${errorText}`);\r\n          }\r\n          // Don't retry on bad request either\r\n          if (response.status === 400) {\r\n            throw new Error(`Bad request ${response.status}: ${errorText}`);\r\n          }\r\n          throw new Error(`HTTP ${response.status}: ${errorText}`);\r\n        }\r\n\r\n        const data = await response.json();\r\n        return data.choices?.[0]?.message?.content ?? '';\r\n      } catch (error) {\r\n        lastError = error;\r\n        // Don't retry on auth or bad request\r\n        if (error.message?.startsWith('Auth error') || error.message?.startsWith('Bad request')) {\r\n          throw error;\r\n        }\r\n        if (attempt < maxRetries - 1) {\r\n          await new Promise(resolve => setTimeout(resolve, delays[attempt] ?? 8000));\r\n        }\r\n      }\r\n    }\r\n    throw lastError;\r\n  }\r\n}",
  "engine/src/prompt-builder.js": "/**\n * PromptBuilder — assembles the full GM prompt in the exact order specified in\n * docs/gm-prompt-LoreLetter.md.\n */\nexport class PromptBuilder {\n  buildDeliveryPrompt({\n    seed, facts, deepHistory, recentHistory, events, gmNotes,\n    senderCharacter, senderLocation, recipientCharacter, recipientLocation,\n    letterBody, senderName, recipientName, sentAt, game,\n  }) {\n    return [\n      { role: 'system', content: this._buildSystemPrompt(game) },\n      { role: 'user', content: this._buildUserMessage({ seed, facts, deepHistory, recentHistory, events, gmNotes, senderCharacter, senderLocation, recipientCharacter, recipientLocation, letterBody, senderName, recipientName, sentAt }) },\n    ];\n  }\n\n  buildSeedPrompt({ worldName, flavour, era, tone, gmStyle, founderCharacter }) {\n    const today = new Date().toISOString().split('T')[0];\n    const system = `You are the Game Master of a living epistolary world.\\nYour only output is a JSON object. You never explain yourself.\\nWrite in third person, past tense. Measured, authoritative, unhurried.\\nThe tone is a chronicle — not a story being told, but history being recorded.\\nNever: purple prose, flowery description, modern idiom, chatty narration.\\nAlways: precise nouns, active verbs, the weight of consequence.`;\n    const user = `You are generating the opening history of a new world.\n\nWorld name: ${worldName ?? flavour.split(' ').slice(0, 4).join(' ')}\nFlavour: ${flavour}\nEra: ${era}\nTone: ${tone}\nGM Style: ${gmStyle}\n\n${this._gmStyleBlock(gmStyle)}\n\nFounder's character: ${founderCharacter?.name ?? 'Unknown'} — ${founderCharacter?.bio ?? ''}\nStarting location: ${founderCharacter?.location ?? 'Unknown'}\n\nProduce:\n1. seed — 250–300 word world introduction. Third person, past tense, chronicle voice. Set scene, era, atmosphere, central tension. Do not resolve anything. End with the world in motion.\n2. first_canon_entry — one canon entry, 80–120 words.\n   Format exactly: ### {Short title}\\\\n*established: ${today} · source: gm-inference*\\\\n\\\\n{prose body}\n3. map_updates — seed the world map with the founder's starting location as the first node.\n   Use a stable lowercase hyphenated id. e.g. \"crull-waystation\". No edges yet unless the\n   starting location is a sub-area of a larger settlement (e.g. \"Kingsland Outskirts\" → also add\n   \"Kingsland\" and connect them with an edge).\n\nRespond with JSON only:\n{\n  \"seed\": string,\n  \"first_canon_entry\": string,\n  \"map_updates\": {\n    \"new_nodes\": [{ \"id\": string, \"label\": string, \"description\": string }],\n    \"new_edges\": [{ \"from\": string, \"to\": string, \"label\": string, \"travel_hours\": integer }] | null\n  }\n}`;\n    return [\n      { role: 'system', content: system },\n      { role: 'user', content: user },\n    ];\n  }\n\n  buildPlayerJoinPrompt({ seed, facts, playerCharacter, playerLocation, characterName, game, existingNodes = [] }) {\n    const today = new Date().toISOString().split('T')[0];\n    const system = `You are the Game Master of a living epistolary world.\nYour only output is a JSON object. You never explain yourself.\nWrite in third person, past tense. Measured, authoritative, unhurried.\nA new character has arrived in the world. Their starting location is player-established fact — it belongs on the world map.`;\n\n    const existingNodesBlock = existingNodes.length > 0\n      ? `EXISTING MAP NODES (do not duplicate these)\n────────────────────────────────────────────\n${existingNodes.map(n => `  id: \"${n.id}\"  label: \"${n.label}\"`).join('\\n')}\n\nIMPORTANT: If the player's starting location \"${playerLocation}\" matches or is essentially the same place as any node above, do NOT add a new_node for it. Instead, set player_location_node_id to the matching existing node's id. Only add to new_nodes if the location is genuinely a new, distinct place not represented above.`\n      : '';\n\n    const user = `A new character has joined the world.\n\nCharacter name: ${characterName}\n${playerCharacter?.trim() ? `Bio:\\n${playerCharacter.trim()}` : ''}\nStarting location: ${playerLocation}\n\n${seed ? `WORLD SEED\\n──────────\\n${seed}` : ''}\n${facts?.trim() ? `\\nESTABLISHED FACTS\\n─────────────────\\n${facts}` : ''}\n${existingNodesBlock ? `\\n${existingNodesBlock}` : ''}\n\nThe character's starting location \"${playerLocation}\" is player-established fact and MUST be represented on the world map — either by matching it to an existing node (preferred if the place is the same) or by adding it as a new node.\n\nIf the location name implies a sub-area of a larger settlement (e.g. \"Kingsland Outskirts\" implies \"Kingsland\"), add both the sub-area AND the parent as separate nodes, with an edge connecting them — unless the parent already exists above.\n\nUse a stable lowercase hyphenated id derived from the location name. e.g. \"brethlaham\", \"kingsland-outskirts\".\n\nRespond ONLY with a single JSON object:\n{\n  \"map_updates\": {\n    \"new_nodes\": [{ \"id\": string, \"label\": string, \"description\": string }],\n    \"new_edges\": [{ \"from\": string, \"to\": string, \"label\": string, \"travel_hours\": integer }] | null\n  },\n  \"canon_addition\": string | null,\n  \"world_event\": string | null,\n  \"gm_notes_addition\": string,\n  \"player_location_node_id\": string\n}\n\ncanon_addition: A brief canon entry (60–100 words) establishing this character's presence in the world.\n  Format: ### {title}\\\\n*established: ${today} · source: gm-inference*\\\\n\\\\n{prose body}\n  null if no canon entry is warranted.\nworld_event: One past-tense sentence recording this character's arrival. Or null.\ngm_notes_addition: Your private notes on this character and how they fit the world. Always populate.\nplayer_location_node_id: The stable node id for the player's current location — either an existing node id from the list above, or the id of a new node you just added. This field is REQUIRED and must never be null.`;\n\n    return [\n      { role: 'system', content: system },\n      { role: 'user', content: user },\n    ];\n  }\n\n  buildChroniclePrompt({ seed, facts, canon, events, characters, game }) {\n    return [\n      {\n        role: 'system',\n        content: `You are a historian writing the closing volume of a chronicle.\\nThird person, past tense, measured and authoritative.\\nWrite a retrospective account of the age just ended.\\nWrite as if centuries have passed and this is received historical record.\\nStructure: era summary, then \"WHAT BECAME OF THEM\" for each named character.`,\n      },\n      {\n        role: 'user',\n        content: `World: ${game.name} — ${game.flavour}\\n\\n## SEED\\n${seed}\\n\\n## ESTABLISHED FACTS\\n${facts}\\n\\n## FULL CANON\\n${canon}\\n\\n## EVENTS\\n${events}\\n\\n## CHARACTERS\\n${characters}\\n\\nWrite the closing chronicle. Output plain prose only, no JSON.`,\n      },\n    ];\n  }\n\n  _buildSystemPrompt(game) {\n    const style = (game?.gm_style ?? 'medium').toLowerCase();\n    const today = new Date().toISOString().split('T')[0];\n    return `You are the Game Master of a living epistolary world. You do not speak to players.\nYou are the invisible hand of history — the force that records, reacts, and remembers.\n\nYour only output is a JSON object. You never explain yourself. You never break character.\nYou never address the players. You write as a historian recording events as they unfold.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nVOICE AND STYLE\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nWrite in third person, past tense. Measured, authoritative, unhurried.\nThe tone is a chronicle being written in real time — not a story being told, but history being recorded.\n\nNever: purple prose, flowery description, modern idiom, chatty narration.\nAlways: precise nouns, active verbs, the weight of consequence.\n\nA good canon entry reads like a page from a historian's notes — specific, factual, faintly ominous.\nA bad one reads like a fantasy novel excerpt.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nGM STYLE\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n${this._gmStyleBlock(style)}\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nWHAT YOU MAY INVENT\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nYou may give form to things players have already implied.\nIf a letter mentions \"the guild leader,\" you may name and characterise them.\nIf a letter references \"the eastern road,\" you may establish its condition and reputation.\nIf a letter hints at a conspiracy, you may record its first concrete detail.\n\nYou may NOT invent named characters, institutions, or locations that have no root in player correspondence\nor player-provided character data (name, bio, starting location).\nThe players are the authors of what exists. You are the author of what it means.\n\nWhen a player's starting location (shown in the SENDER or RECIPIENT context block as \"Last known location\")\nis a named place not yet on the map, you MUST add it as a new map node. This is player-established fact,\nnot invention. If the location name implies a parent settlement (e.g. \"Kingsland Outskirts\" implies\n\"Kingsland\"), also add the parent as a separate node and connect the two with an appropriate edge.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nCANON RULES\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nCanon is append-only. You add to it. You never revise it.\nEvery fact you establish becomes permanent. Write nothing you would need to undo.\n\nAll entries are equal — the most recent facts are considered current.\nOlder entries remain visible and may be built upon, but never erased or contradicted.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nCONTRADICTION HANDLING\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nIf a player's letter implies something that appears to contradict existing canon, do not reject it.\nDo not flag it. Do not note the tension.\n\nInstead: find the most dramatically interesting explanation that makes both things simultaneously\ntrue, and record it as established history.\n\nThe world builds around what players write. Contradictions are not errors — they are the world\nbecoming more complex than anyone expected.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nWHEN TO ACT VS. PASS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nNot every letter changes the world. Use your judgment.\n\nAdd a canon entry only when the letter contains something the world should remember:\nan arrival, a departure, a revelation, a shift in relationship or power, an implied event\nwith consequences beyond the two correspondents.\n\nA letter of pure personal feeling between close friends, with no reference to the world\nbeyond themselves, may warrant only a location update and a gm_notes addition.\nIn that case, set canon_addition and world_event to null.\n\nWhen in doubt: less is more. A sparse canon is more coherent than an overcrowded one.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nWORLD STRUCTURE EXTRACTION\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nAfter every delivery you may extract structured world data. These fields are strictly optional —\nonly populate them when the letter genuinely canonizes something new.\n\nExtract conservatively. Only add a person, place, or faction to structured data if it is\ngenuinely established in this letter — not merely mentioned speculatively.\n\nPEOPLE (new_people / updated_people):\n- new_people: NPCs the GM is introducing for the first time. NEVER include player characters.\n- If a letter names an individual — any named person who is clearly real in the world — add them.\n  A name is explicit enough. You do not need lengthy description to justify the entry.\n  If little is known, a sparse description is fine: \"Known to [sender]. Little else recorded.\"\n- updated_people: existing NPCs whose status or description has meaningfully changed.\n- id: stable, lowercase, hyphenated slug. Once set, never changed. e.g. \"warden-holt\"\n- status: one short phrase only. e.g. \"whereabouts unknown\", \"last seen in Crull\", \"deceased\"\n- description: 1–3 sentences. What the world knows about them. Sparse is fine for new names.\n\nFACTIONS (new_factions / updated_factions):\n- Organizations, guilds, governments, and named groups only.\n- id: stable slug. e.g. \"cartographers-guild\"\n- disposition: one word or short phrase. e.g. \"allied\", \"hostile\", \"uncertain\", \"defunct\"\n- description: 1–3 sentences. What is publicly known.\n\nMAP (map_updates):\n- new_nodes: named locations being established for the first time.\n  id: stable slug e.g. \"crull-waystation\", label: display name, description: 1–2 sentences.\n- new_edges: routes or distances between two known nodes being established.\n  from/to: existing node ids. label: travel description e.g. \"three days by road\". travel_hours: integer.\n- Edges are bidirectional by default. Only add an edge when the letter implies a specific route or distance.\n- Do not add nodes for vague references (\"somewhere in the east\"). Only named, established places.\n- IMPORTANT: If a sender or recipient's \"Last known location\" (shown in the SENDER/RECIPIENT context\n  blocks) is a named place not yet in the map, you MUST add it as a new node. Player-given starting\n  locations are established facts that belong on the map. If the name implies a sub-area of a larger\n  settlement (e.g. \"Kingsland Outskirts\"), add both the sub-area AND the parent settlement as nodes,\n  with an edge connecting them.\n\nTIMELINE (timeline_entry):\n- One entry per delivery, only when canon_addition is non-null.\n- id: unique slug e.g. \"entry-crull-smoke-001\"\n- summary: 1–2 sentences. What happened, in plain English.\n- tags: array of node ids and faction ids relevant to this entry.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nOUTPUT FORMAT\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\nRespond ONLY with a single JSON object. No preamble. No commentary. No markdown fences.\n\n{\n  \"canon_addition\": string | null,\n  \"world_event\": string | null,\n  \"gm_notes_addition\": string | null,\n  \"sender_location_update\": string | null,\n  \"recipient_location_update\": string | null,\n  \"sender_location_node_id\": string | null,\n  \"recipient_location_node_id\": string | null,\n  \"sender_character_update\": string | null,\n  \"recipient_character_update\": string | null,\n  \"next_letter_travel_hours\": integer,\n  \"map_updates\": { \"new_nodes\": [...] | null, \"new_edges\": [...] | null } | null,\n  \"new_people\": [...] | null,\n  \"updated_people\": [...] | null,\n  \"new_factions\": [...] | null,\n  \"updated_factions\": [...] | null,\n  \"timeline_entry\": { \"id\": string, \"summary\": string, \"tags\": [...] } | null\n}\n\nField rules:\n\ncanon_addition\n  A new entry for canon.md. Written in chronicle voice. 80–150 words.\n  Begins with a heading: ### {Short title of what is being established}\n  Followed by: *established: ${today} · source: gm-inference*\n  Then the entry body. No bullet points. Flowing prose. Spare and precise.\n  null if this letter warrants no canon change.\n\nworld_event\n  A single sentence, past tense, factual. Recorded in events.md.\n  Example: \"Maren Voss departed Crull by river barge, destination unstated.\"\n  null if no event worth recording occurred.\n\ngm_notes_addition\n  Private. Never shown to players. Your scratchpad.\n  Record: implied motivations, emerging conspiracies, tensions held in reserve.\n  1–4 sentences. Plain prose, not chronicle voice.\n  Always populate this — even if canon_addition is null.\n\nsender_location_update / recipient_location_update\n  Short plain-English location string. null if unchanged or cannot be inferred.\n\nsender_location_node_id / recipient_location_node_id\n  If the sender/recipient's current location corresponds to a node that exists (or was just added)\n  in map.json, provide its stable node id here. e.g. \"crull-waystation\".\n  This is used to show player character positions on the map.\n  Check the SENDER / RECIPIENT \"Last known location\" fields carefully — if the location text\n  matches (even loosely) an existing map node, always set this field. Only set to null if the\n  character's location is genuinely unknown or not on the map at all.\n\nsender_character_update / recipient_character_update\n  Full updated character.md content if something meaningful has changed. null otherwise.\n\nnext_letter_travel_hours\n  Integer. Never 0. Minimum 1.\n\nmap_updates / new_people / updated_people / new_factions / updated_factions / timeline_entry\n  All optional. null if nothing applies. See WORLD STRUCTURE EXTRACTION above.`;\n  }\n\n  _gmStyleBlock(style) {\n    const s = (style ?? '').toLowerCase();\n    if (s === 'gentle') {\n      return `The world is forgiving. Consequences are present but recoverable. History records difficulty\nwithout cruelty — tensions simmer, rarely boil. Characters are resilient. The world bends\ntoward warmth even in dark settings.`;\n    }\n    if (s === 'dramatic') {\n      return `The world bends toward interesting trouble. When a letter opens a door, something walks through it.\nFactions shift. Old alliances become uncertain. The world reads what players write and finds the\nmost consequential interpretation. You may introduce one new named entity per delivery (person,\nplace, or institution) if the letter clearly implies its existence — but only one, and only then.`;\n    }\n    return `The world has weight. Consequences follow from actions. History does not protect characters\nfrom the implications of their choices. What players write echoes — sometimes quietly, sometimes\nnot. The world is neither hostile nor kind. It simply remembers.`;\n  }\n\n  _buildUserMessage({\n    seed, facts, deepHistory, recentHistory, events, gmNotes,\n    senderCharacter, senderLocation, recipientCharacter, recipientLocation,\n    letterBody, senderName, recipientName, sentAt,\n  }) {\n    const blocks = [];\n\n    if (seed) blocks.push(`WORLD SEED\\n──────────\\n${seed}`);\n\n    if (facts?.trim()) {\n      blocks.push(`ESTABLISHED FACTS — TREAT THESE AS IMMUTABLE\\n─────────────────────────────────────────────\\nThe following facts have been extracted from canon and must not be contradicted.\\nIf the letter implies conflict with any of these, apply the contradiction handling rule.\\n\\n${facts}`);\n    }\n\n    if (deepHistory?.trim()) {\n      blocks.push(`DEEP HISTORY — SUMMARISED RECORD\\n──────────────────────────────────\\n${deepHistory}`);\n    }\n\n    if (recentHistory?.trim()) {\n      blocks.push(`RECENT HISTORY — VERBATIM RECORD\\n──────────────────────────────────\\n${recentHistory}`);\n    }\n\n    if (events?.trim()) {\n      blocks.push(`RECENT WORLD EVENTS\\n────────────────────\\n${events}`);\n    }\n\n    if (gmNotes?.trim()) {\n      blocks.push(`GM NOTES — PRIVATE\\n───────────────────\\nThese notes are not visible to players. They are your private continuity record.\\n\\n${gmNotes}`);\n    }\n\n    blocks.push(`SENDER\\n───────\\nCharacter: ${senderCharacter || senderName}\\nLast known location: ${senderLocation || 'Unknown'}`);\n    blocks.push(`RECIPIENT\\n──────────\\nCharacter: ${recipientCharacter || recipientName}\\nLast known location: ${recipientLocation || 'Unknown'}`);\n\n    const sentDate = sentAt\n      ? new Date(sentAt * 1000).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })\n      : 'unknown date';\n    blocks.push(`THE LETTER\\n───────────\\nFrom: ${senderName}\\nTo: ${recipientName}\\nIn-world date sent: ${sentDate}\\n\\n${letterBody}`);\n\n    blocks.push(`Now produce your JSON response. Remember:\n- No preamble, no explanation, no markdown fences.\n- Raw JSON only.\n- canon_addition must begin with the ### heading format (### {Short title}) if not null.\n- gm_notes_addition is always populated.\n- next_letter_travel_hours is always an integer ≥ 1.`);\n\n    return blocks.join('\\n\\n---\\n\\n');\n  }\n\n  buildChapterizePrompt({ seed, facts, canonEntries, chapterNumber, game }) {\n    const system = `You are a historian writing chapter summaries for a living epistolary world.\nThird person, past tense, measured and authoritative.\nWrite as if recording a defined period of history that has now closed.\nYour summary should be readable by players who want to catch up on the story so far.\nYour only output is a JSON object. No preamble, no markdown fences.`;\n    const blocks = [];\n    if (seed?.trim()) blocks.push(`WORLD SEED\\n──────────\\n${seed}`);\n    if (facts?.trim()) blocks.push(`ESTABLISHED FACTS\\n─────────────────\\n${facts}`);\n    blocks.push(`CANON ENTRIES TO SUMMARIZE INTO CHAPTER ${chapterNumber}\\n${'─'.repeat(52)}\\n${canonEntries}`);\n    blocks.push(`Write Chapter ${chapterNumber} of the world chronicle.\nProduce a short title (3–6 words) and a summary paragraph (3–5 sentences) that captures the essential events, turning points, and consequences of this period. Write for players — make it engaging and informative. Chronicle voice: third person, past tense, spare and precise.\nRespond with JSON only:\n{\n  \"chapter_title\": string,\n  \"chapter_summary\": string\n}`);\n    return [\n      { role: 'system', content: system },\n      { role: 'user', content: blocks.join('\\n\\n---\\n\\n') },\n    ];\n  }\n}",
  "engine/src/status-writer.js": "/**\r\n * StatusWriter — writes .gm-status.json after every run.\r\n * Always runs, even on failure.\r\n */\r\nexport class StatusWriter {\r\n  constructor(worldState) {\r\n    this.ws = worldState;\r\n  }\r\n\r\n  async write({ trigger, lettersProcessed = 0, success, error = null, compressionRan = false, deliveries = [], extraData = {} }) {\r\n    const status = {\r\n      timestamp: new Date().toISOString(),\r\n      trigger,\r\n      success,\r\n      lettersProcessed,\r\n      compressionRan,\r\n      deliveries,\r\n      error: error ? String(error) : null,\r\n      ...extraData,\r\n    };\r\n    await this.ws.writeGmStatus(status);\r\n    return status;\r\n  }\r\n}",
  "engine/src/world-state.js": "import fs from 'fs/promises';\nimport path from 'path';\nimport matter from 'gray-matter';\n\n/**\n * WorldState — all file reads and writes for the game repo.\n * Enforces append-only access to canon.md (except compression rewrites and character updates).\n */\nexport class WorldState {\n  constructor(repoPath) {\n    this.repoPath = repoPath;\n  }\n\n  _resolve(...parts) {\n    return path.join(this.repoPath, ...parts);\n  }\n\n  async readFile(relPath) {\n    try {\n      return await fs.readFile(this._resolve(relPath), 'utf8');\n    } catch (e) {\n      if (e.code === 'ENOENT') return null;\n      throw e;\n    }\n  }\n\n  async writeFile(relPath, content) {\n    const full = this._resolve(relPath);\n    await fs.mkdir(path.dirname(full), { recursive: true });\n    await fs.writeFile(full, content, 'utf8');\n  }\n\n  /** APPEND-ONLY — the only way to add to canon.md (outside of compression) */\n  async appendToCanon(text) {\n    const filePath = this._resolve('world/canon.md');\n    await fs.mkdir(path.dirname(filePath), { recursive: true });\n    await fs.appendFile(filePath, '\\n' + text, 'utf8');\n  }\n\n  async appendToFile(relPath, text) {\n    const full = this._resolve(relPath);\n    await fs.mkdir(path.dirname(full), { recursive: true });\n    await fs.appendFile(full, '\\n' + text, 'utf8');\n  }\n\n  /** Parse canon into { deep, recent } section text only, no headers */\n  parseSections(canonText) {\n    const deepMatch = canonText.match(\n      /## DEEP HISTORY\\n\\*\\[.*?\\]\\*\\n([\\s\\S]*?)(?=\\n*---\\n*## RECENT HISTORY|$)/\n    );\n    const recentMatch = canonText.match(\n      /## RECENT HISTORY\\n\\*\\[.*?\\]\\*\\n([\\s\\S]*)$/\n    );\n    return {\n      deep: deepMatch ? deepMatch[1].trim() : '',\n      recent: recentMatch ? recentMatch[1].trim() : '',\n    };\n  }\n\n  /** Rebuild canon.md from deep and recent section content */\n  rebuildCanon(deep, recent) {\n    const deepBlock = deep?.trim() ?? '';\n    const recentBlock = recent?.trim() ?? '';\n    return [\n      '## DEEP HISTORY',\n      '*[summarized — compressed from earlier records]*',\n      '',\n      deepBlock,\n      '',\n      '---',\n      '',\n      '## RECENT HISTORY',\n      '*[verbatim — last recorded entries]*',\n      '',\n      recentBlock,\n      '',\n    ].join('\\n');\n  }\n\n  /**\n   * Atomic chapterize: moves all RECENT HISTORY entries into DEEP HISTORY\n   * and clears RECENT HISTORY. Single read, single write.\n   * Returns the recent content that was moved, so the caller can use it\n   * for chapter summary generation.\n   */\n  async chapterizeCanon() {\n    const current = await this.readCanon();\n    const { deep, recent } = this.parseSections(current);\n    const newDeep = deep ? `${deep}\\n\\n${recent}` : recent;\n    const rebuilt = this.rebuildCanon(newDeep, '');\n    await this.writeFile('world/canon.md', rebuilt);\n    return recent;\n  }\n\n  /**\n   * Replace only the RECENT HISTORY section. DEEP HISTORY is untouched.\n   * Used by canon-manager after compression.\n   */\n  async replaceRecentHistory(newRecentContent) {\n    const current = await this.readCanon();\n    const { deep } = this.parseSections(current);\n    const rebuilt = this.rebuildCanon(deep, newRecentContent);\n    await this.writeFile('world/canon.md', rebuilt);\n  }\n\n  /**\n   * Append a compressed block to DEEP HISTORY. RECENT HISTORY is untouched.\n   * Used by canon-manager compression.\n   */\n  async appendToDeepHistory(compressedBlock) {\n    const current = await this.readCanon();\n    const { deep, recent } = this.parseSections(current);\n    const newDeep = deep ? `${deep}\\n\\n${compressedBlock}` : compressedBlock;\n    const rebuilt = this.rebuildCanon(newDeep, recent);\n    await this.writeFile('world/canon.md', rebuilt);\n  }\n\n  async readCanon() {\n    return await this.readFile('world/canon.md') ?? '';\n  }\n\n  async readFacts() {\n    return await this.readFile('world/canon-facts.md') ?? '';\n  }\n\n  /** Returns only the last eventsWindow entries from events.md */\n  async readEvents(eventsWindow = 20) {\n    const raw = await this.readFile('world/events.md') ?? '';\n    const lines = raw.split('\\n');\n    // Split on ### date headers\n    const entries = raw.split(/(?=\\n### )/).filter(s => s.trim());\n    if (entries.length <= eventsWindow) return raw;\n    return entries.slice(-eventsWindow).join('');\n  }\n\n  async readGmNotes() {\n    return await this.readFile('world/gm-notes.md') ?? '';\n  }\n\n  async readSeed() {\n    return await this.readFile('world/seed.md') ?? '';\n  }\n\n  async readGameJson() {\n    const raw = await this.readFile('config/game.json');\n    return raw ? JSON.parse(raw) : null;\n  }\n\n  async writeGameJson(data) {\n    await this.writeFile('config/game.json', JSON.stringify(data, null, 2));\n  }\n\n  async readEngineJson() {\n    const raw = await this.readFile('config/engine.json');\n    return raw ? JSON.parse(raw) : {};\n  }\n\n  async readCharacter(playerId) {\n    return await this.readFile(`players/${playerId}/character.md`) ?? '';\n  }\n\n  async readLocation(playerId) {\n    return await this.readFile(`players/${playerId}/location.md`) ?? '';\n  }\n\n  async writeLocation(playerId, content) {\n    await this.writeFile(`players/${playerId}/location.md`, content);\n  }\n\n  /** Full rewrite of character.md — only non-append write for player files */\n  async updateCharacter(playerId, content) {\n    await this.writeFile(`players/${playerId}/character.md`, content);\n  }\n\n  async writeSeed(content) {\n    await this.writeFile('world/seed.md', content);\n  }\n\n  /** List all letters in /letters/pending/ */\n  async listPendingLetters() {\n    const dir = this._resolve('letters/pending');\n    try {\n      const files = await fs.readdir(dir);\n      return files.filter(f => f.endsWith('.md') && f !== '.gitkeep').map(f => `letters/pending/${f}`);\n    } catch {\n      return [];\n    }\n  }\n\n  /** Parse a letter file — returns { frontmatter, body } */\n  async parseLetter(relPath) {\n    const raw = await this.readFile(relPath);\n    if (!raw) return null;\n    const parsed = matter(raw);\n    return { frontmatter: parsed.data, body: parsed.content.trim() };\n  }\n\n  /** Move letter from pending to delivered, mark delivered: true */\n  async deliverLetter(relPath) {\n    const raw = await this.readFile(relPath);\n    if (!raw) return;\n    const parsed = matter(raw);\n    parsed.data.delivered = true;\n    const updated = matter.stringify(parsed.content, parsed.data);\n    const filename = path.basename(relPath);\n    await this.writeFile(`letters/delivered/${filename}`, updated);\n    await fs.unlink(this._resolve(relPath));\n  }\n\n  async writeChronicle(content) {\n    await this.writeFile('world/chronicle.md', content);\n  }\n\n  async readChronicle() {\n    return await this.readFile('world/chronicle.md') ?? '';\n  }\n\n  async writeGmStatus(data) {\n    await this.writeFile('.gm-status.json', JSON.stringify(data, null, 2));\n  }\n\n  async readGmStatus() {\n    const raw = await this.readFile('.gm-status.json');\n    return raw ? JSON.parse(raw) : null;\n  }\n\n  // ─── World lore JSON files ────────────────────────────────────────────────\n\n  static _worldJsonDefaults = {\n    'world/map.json':      { nodes: [], edges: [], player_locations: {} },\n    'world/people.json':   { people: [] },\n    'world/factions.json': { factions: [] },\n    'world/timeline.json': { entries: [] },\n    'world/chapters.json':  { chapters: [] },\n  };\n\n  async readWorldJson(relPath) {\n    const raw = await this.readFile(relPath);\n    const def = JSON.parse(JSON.stringify(WorldState._worldJsonDefaults[relPath] ?? {}));\n    if (!raw) return def;\n    try { return JSON.parse(raw); } catch { return def; }\n  }\n\n  async writeWorldJson(relPath, data) {\n    await this.writeFile(relPath, JSON.stringify(data, null, 2));\n  }\n\n  /** Upsert nodes and edges into world/map.json. Skips duplicates by id / from:to key. */\n  async updateMapJson({ new_nodes, new_edges }, now) {\n    const map = await this.readWorldJson('world/map.json');\n    const existingNodeIds = new Set(map.nodes.map(n => n.id));\n    const existingEdgeKeys = new Set([\n      ...map.edges.map(e => `${e.from}:${e.to}`),\n      ...map.edges.map(e => `${e.to}:${e.from}`),\n    ]);\n    for (const node of (new_nodes ?? [])) {\n      if (!existingNodeIds.has(node.id)) {\n        map.nodes.push({ ...node, first_mentioned: now });\n        existingNodeIds.add(node.id);\n      }\n    }\n    for (const edge of (new_edges ?? [])) {\n      const key = `${edge.from}:${edge.to}`;\n      if (!existingEdgeKeys.has(key)) {\n        map.edges.push({ ...edge, first_mentioned: now });\n        existingEdgeKeys.add(key);\n        existingEdgeKeys.add(`${edge.to}:${edge.from}`);\n      }\n    }\n    await this.writeWorldJson('world/map.json', map);\n  }\n\n  /** Add new NPCs / apply status+description updates into world/people.json. */\n  async updatePeopleJson({ new_people, updated_people }, now) {\n    const data = await this.readWorldJson('world/people.json');\n    for (const person of (new_people ?? [])) {\n      if (!data.people.find(p => p.id === person.id)) {\n        data.people.push({ ...person, first_mentioned: now, last_updated: now });\n      }\n    }\n    for (const update of (updated_people ?? [])) {\n      const existing = data.people.find(p => p.id === update.id);\n      if (existing) {\n        if (update.description != null) existing.description = update.description;\n        if (update.status != null) existing.status = update.status;\n        existing.last_updated = now;\n      }\n    }\n    await this.writeWorldJson('world/people.json', data);\n  }\n\n  /** Add new factions / apply updates into world/factions.json. */\n  async updateFactionsJson({ new_factions, updated_factions }, now) {\n    const data = await this.readWorldJson('world/factions.json');\n    for (const faction of (new_factions ?? [])) {\n      if (!data.factions.find(f => f.id === faction.id)) {\n        data.factions.push({ ...faction, first_mentioned: now, last_updated: now });\n      }\n    }\n    for (const update of (updated_factions ?? [])) {\n      const existing = data.factions.find(f => f.id === update.id);\n      if (existing) {\n        if (update.description != null) existing.description = update.description;\n        if (update.disposition != null) existing.disposition = update.disposition;\n        existing.last_updated = now;\n      }\n    }\n    await this.writeWorldJson('world/factions.json', data);\n  }\n\n  /** Append a single entry to world/timeline.json. Skips if id already exists. */\n  async appendTimelineEntry(entry, now) {\n    const data = await this.readWorldJson('world/timeline.json');\n    if (!data.entries.find(e => e.id === entry.id)) {\n      data.entries.push({ ...entry, timestamp: now });\n    }\n    await this.writeWorldJson('world/timeline.json', data);\n  }\n\n  // ─── Chapters JSON ───────────────────────────────────────────────────────\n  async readChaptersJson() {\n    return await this.readWorldJson('world/chapters.json');\n  }\n  async appendChapterJson(chapter) {\n    const data = await this.readChaptersJson();\n    data.chapters.push(chapter);\n    await this.writeWorldJson('world/chapters.json', data);\n  }\n    /** Record which map node a player character is currently at. */\n  async updatePlayerLocationOnMap(playerId, nodeId) {\n    const map = await this.readWorldJson('world/map.json');\n    if (!map.player_locations) map.player_locations = {};\n    // Only update if the node actually exists in the map\n    if (nodeId && map.nodes.find(n => n.id === nodeId)) {\n      map.player_locations[playerId] = nodeId;\n      await this.writeWorldJson('world/map.json', map);\n    }\n  }\n}"
};
